// DHCP Pool Simulator untuk VLAN 10/20 dan WLAN
// Jalankan dengan Node.js
function ipToInt(ip){ const p=ip.split('.').map(Number); return ((p[0]*256+p[1])*256+p[2])*256+p[3]; }
function intToIp(n){ return [ (n>>>24)&255, (n>>>16)&255, (n>>>8)&255, n&255 ].join('.'); }
function rangeInfo(startIp,endIp){ const s=ipToInt(startIp); const e=ipToInt(endIp); if(e<s) return {ok:false,message:'End IP lebih kecil dari Start IP'}; return {ok:true,start:startIp,end:endIp,total:(e-s+1)}; }
const pools=[
  {name:'vlan1-Siswa', start:'192.168.40.10', end:'192.168.40.50'},
  {name:'vlan2-Guru', start:'192.168.60.10', end:'192.168.60.50'},
  {name:'wlan1', start:'192.168.20.10', end:'192.168.20.50'}
];
for(const p of pools){ const r=rangeInfo(p.start,p.end); console.log(`${p.name}:`, r.ok?`OK range ${r.start} - ${r.end}, total IP = ${r.total}` : r.message); }

// Challenge: coba ganti start/end pada salah satu pool lalu lihat apakah total berubah dan apakah range masih valid.

// VLAN Summary Generator (bantu cek konfigurasi IP & DHCP pool)
const config={
  vlan10:{name:'vlan1-Siswa', id:10, gateway:'192.168.40.1/24', poolStart:'192.168.40.10', poolEnd:'192.168.40.50'},
  vlan20:{name:'vlan2-Guru', id:20, gateway:'192.168.60.1/24', poolStart:'192.168.60.10', poolEnd:'192.168.60.50'},
  wlan:{name:'wlan1', gateway:'192.168.20.1/24', poolStart:'192.168.20.10', poolEnd:'192.168.20.50'}
};
function maskFromCidr(cidr){ const [ip,mask]=cidr.split('/'); return `gateway=${ip} mask=/${mask}`; }
console.log('=== RINGKASAN ===');
console.log(`${config.vlan10.name} (VLAN ID ${config.vlan10.id})`, maskFromCidr(config.vlan10.gateway), `DHCP=${config.vlan10.poolStart}-${config.vlan10.poolEnd}`);
console.log(`${config.vlan20.name} (VLAN ID ${config.vlan20.id})`, maskFromCidr(config.vlan20.gateway), `DHCP=${config.vlan20.poolStart}-${config.vlan20.poolEnd}`);
console.log(`${config.wlan.name}`, maskFromCidr(config.wlan.gateway), `DHCP=${config.wlan.poolStart}-${config.wlan.poolEnd}`);

